// Width as a pitch wobble: vibrato depth in semitones covering half the peak width.
const wobble = (p, i) => 12 * Math.log2(1 + p.width[i] / (2 * p.freq[i]))

// chord: all peaks sounding together as sine tones.
// pitch = freq, loudness = D, vibrato depth = width 
const chord = p => stack(...p.freq.map((f, i) =>
  freq(f).s("sine")
    .gain(0.6 * p.D[i] / Math.sqrt(p.freq.length))
    .vib(4).vibmod(wobble(p, i))
))

// Sharpness of a peak: Q = freq / width. Sharp (high Q) peaks are long-lived vibrations. 
// A peak's lifetime is ~ 1 / (pi * width) scaled into a reasonable range for audible decay times.
const sharpness = (p, i) => p.freq[i] / p.width[i]
const ringTime = (p, i) => Math.min(2, Math.max(0.05, 0.04 * sharpness(p, i)))

// arp: peaks one after another, low to high, in one cycle.
//  pitch = freq, loudness = D, ring time = sharpness
const arp = p => seq(...p.freq.map((f, i) =>
  freq(f).s("sine").gain(p.D[i]).decay(ringTime(p, i)).sustain(0)
))

// Sharpness of a peak: Q = freq / width. Sharp (high Q) peaks are long-lived vibrations. 
// A peak's lifetime is ~ 1 / (pi * width) scaled into a reasonable range for audible decay times.
const sharpness = (p, i) => p.freq[i] / p.width[i]
const ringTime = (p, i) => Math.min(2, Math.max(0.05, 0.04 * sharpness(p, i)))

// pluck: the chord struck at once and left to ring, each peak decaying at its own rate.
const pluck = p => stack(...p.freq.map((f, i) =>
  freq(f).s("triangle")
    .gain(p.D[i] / Math.sqrt(p.freq.length))
    .decay(ringTime(p, i)).sustain(0)
))

