const ringTime = (p, i) => Math.min(2, Math.max(0.05, 0.04 * sharpness(p, i)))

// spectrum: each peak is a band of filtered noise centred on freq with bandwidth = width.
const spectrum = p => stack(...p.freq.map((f, i) =>
  s("pink").bpf(f).bpq(sharpness(p, i)).gain(p.D[i])
))
